The deliberation pinpointed the bug: I quoted `"$FILES"`, so the multi-line list was passed as a single nonexistent filename (errors hidden by `2>/dev/null`), yielding 0 — while the `*.log` glob worked, which is why totals matched. Let me rerun with proper word splitting, plus a fully independent awk check keyed on each line's own timestamp.<tool_call>bash<arg_key>command</arg_key><arg_value>cd /app/logs
get_dates() { python3 -c "
from datetime import date,timedelta
y1,m1,d1=map(int,'$1'.split('-')); y2,m2,d2=map(int,'$2'.split('-'))
d=date(y1,m1,d1); end=date(y2,m2,d2)
while d<=end:
    print(d.isoformat()); d+=timedelta(days=1)"; }
count() { grep -h "\[$2\]" $1 | wc -l; }
echo "--- grep-based (unquoted file list) ---"
for spec in "today:2025-08-12:2025-08-12" "last_7_days:2025-08-06:2025-08-12" "last_30_days:2025-07-14:2025-08-12" "month_to_date:2025-08-01:2025-08-12"; do
  P=${spec%%:*}; R=${spec#*:}; S=${R%%:*}; E=${R##*:}
  F=$(get_dates $S $E)
  for sev in ERROR WARNING INFO; do echo "$P,$sev,$(count "$F" $sev)"; done
done
echo "--- independent awk (keyed on line's own timestamp date) ---"
awk '{d=substr($1,1,10); s=substr($3,2,length($3)-2); c[d","s]++}
 END{t="2025-08-12";
  n=split("2025-08-12 2025-08-06 2025-07-14 2025-08-01",lo," ");
  hi[1]=t;hi[2]=t;hi[3]=t;hi[4]=t;
  split("ERROR WARNING INFO",sev," ");
  pn[1]="today";pn[2]="last_7_days";pn[3]="last_30_days";pn[4]="month_to_date";
  for(p=1;p<=4;p++) for(i=1;i<=3;i++){cnt=0;
    for(k in c){split(k,a,","); if(a[2]==sev[i] && a[1]>=lo[p] && a[1]<=hi[p]) cnt+=c[k]}
    print pn[p]","sev[i]","cnt}}' *.log | sort
echo "--- filename-date vs line-timestamp mismatches (expect 0) ---"
for f in *.log; do fd=${f%%_*}; awk -v fd=$fd '$1!=fd{n++} END{if(n>0) print FILENAME, n}' "$f"; done | head -5
echo "--- CSV for comparison ---"; cat /app/summary.csv</arg_value></tool_call>
